`default_nettype none

// Synthesizable standalone user design used to validate the native/direct
// RERAM_CIM_32x32 interface.  The controller issues SET and RESET commands and
// checks the automatic readback generated by each programming operation.
module reram_cim_32x32_direct_smoke (
    input  wire       clk1,
    input  wire       rst,
    input  wire       start,

    output wire       busy,
    output wire       done,
    output wire       pass,
    output wire       fail,
    output wire [7:0] failure_code,
    output wire [2:0] accepted_count,
    output wire [2:0] result_count,
    output wire [1:0] set_result_mode,
    output wire [4:0] set_result_column,
    output wire [1:0] reset_result_mode,
    output wire [4:0] reset_result_column
);

    wire        cim_cmd_valid;
    wire        cim_cmd_ready;
    wire [1:0]  cim_mode;
    wire [4:0]  cim_row_index;
    wire [4:0]  cim_col_index;
    wire [7:0]  cim_pwm_data;
    wire        cim_compute_last;
    wire        cim_compute_all_columns;
    wire        cim_result_valid;
    wire        cim_result_ready;
    wire [20:0] cim_result_data;
    wire        cim_result_last;
    wire [2:0]  cim_error;
    wire        cim_error_valid;
    wire [20:0] set_auto_result;
    wire [20:0] reset_auto_result;

    sky130_bmlabs_reram__cim32x32_direct_smoke_controller i_controller (
        .clk_i                         (clk1),
        .rst_i                         (rst),
        .start_i                       (start),
        .interface_sel                 (),
        .cim_i_Levelsh_enable          (),
        .cim_i_target_set1             (),
        .cim_i_target_set2             (),
        .cim_i_target_reset1           (),
        .cim_i_target_reset2           (),
        .cim_i_no_of_clk_cycles        (),
        .cim_i_counter_value           (),
        .cim_i_tdc_time_out            (),
        .cim_i_tdc_dead_time           (),
        .cim_i_cmd_valid               (cim_cmd_valid),
        .cim_o_cmd_ready               (cim_cmd_ready),
        .cim_i_mode                    (cim_mode),
        .cim_i_row_index               (cim_row_index),
        .cim_i_col_index               (cim_col_index),
        .cim_i_pwm_data                (cim_pwm_data),
        .cim_i_compute_last            (cim_compute_last),
        .cim_i_compute_all_columns     (cim_compute_all_columns),
        .cim_o_result_valid            (cim_result_valid),
        .cim_i_result_ready            (cim_result_ready),
        .cim_o_result_data             (cim_result_data),
        .cim_o_result_last             (cim_result_last),
        .cim_o_error                   (cim_error),
        .cim_o_error_valid             (cim_error_valid),
        .busy_o                        (busy),
        .done_o                        (done),
        .pass_o                        (pass),
        .fail_o                        (fail),
        .state_o                       (),
        .failure_code_o                (failure_code),
        .set_auto_result_o             (set_auto_result),
        .reset_auto_result_o           (reset_auto_result),
        .accepted_count_o              (accepted_count),
        .result_count_o                (result_count)
    );

    // The FPGA primitive exposes the direct CIM boundary as scalar pins.
    // Configuration values match the defaults in the smoke-test controller.
    RERAM_CIM_32x32 #(
        .TARGET_SET1      (16'h6472),
        .TARGET_SET2      (16'h0003),
        .TARGET_RESET1    (16'h000B),
        .TARGET_RESET2    (16'h462B),
        .NO_OF_CLK_CYCLES (10'd5),
        .COUNTER_VALUE    (10'd5),
        .TDC_TIME_OUT     (7'd62),
        .TDC_DEAD_TIME    (2'd2)
    ) i_RERAM_CIM_32x32 (
        .CLK                       (clk1),
        .RST                       (rst),
        .CMD_VALID                 (cim_cmd_valid),
        .CMD_READY                 (cim_cmd_ready),
        .MODE0                     (cim_mode[0]),
        .MODE1                     (cim_mode[1]),
        .ROW_INDEX0                (cim_row_index[0]),
        .ROW_INDEX1                (cim_row_index[1]),
        .ROW_INDEX2                (cim_row_index[2]),
        .ROW_INDEX3                (cim_row_index[3]),
        .ROW_INDEX4                (cim_row_index[4]),
        .COL_INDEX0                (cim_col_index[0]),
        .COL_INDEX1                (cim_col_index[1]),
        .COL_INDEX2                (cim_col_index[2]),
        .COL_INDEX3                (cim_col_index[3]),
        .COL_INDEX4                (cim_col_index[4]),
        .PWM_DATA0                 (cim_pwm_data[0]),
        .PWM_DATA1                 (cim_pwm_data[1]),
        .PWM_DATA2                 (cim_pwm_data[2]),
        .PWM_DATA3                 (cim_pwm_data[3]),
        .PWM_DATA4                 (cim_pwm_data[4]),
        .PWM_DATA5                 (cim_pwm_data[5]),
        .PWM_DATA6                 (cim_pwm_data[6]),
        .PWM_DATA7                 (cim_pwm_data[7]),
        .COMPUTE_LAST              (cim_compute_last),
        .COMPUTE_ALL_COLUMNS       (cim_compute_all_columns),
        .BUSY                      (),
        .COMMAND_ACCEPTED          (),
        .COMPUTE_PENDING           (),
        .ERROR0                    (cim_error[0]),
        .ERROR1                    (cim_error[1]),
        .ERROR_VALID               (cim_error_valid),
        .OPERATION_DONE            (),
        .PROGRAM_READBACK_ACTIVE   (),
        .RESULT_VALID              (cim_result_valid),
        .RESULT_READY              (cim_result_ready),
        .RESULT_DATA0              (cim_result_data[0]),
        .RESULT_DATA1              (cim_result_data[1]),
        .RESULT_DATA2              (cim_result_data[2]),
        .RESULT_DATA3              (cim_result_data[3]),
        .RESULT_DATA4              (cim_result_data[4]),
        .RESULT_DATA5              (cim_result_data[5]),
        .RESULT_DATA6              (cim_result_data[6]),
        .RESULT_DATA7              (cim_result_data[7]),
        .RESULT_DATA8              (cim_result_data[8]),
        .RESULT_DATA9              (cim_result_data[9]),
        .RESULT_DATA10             (cim_result_data[10]),
        .RESULT_DATA11             (cim_result_data[11]),
        .RESULT_DATA12             (cim_result_data[12]),
        .RESULT_DATA13             (cim_result_data[13]),
        .RESULT_DATA14             (cim_result_data[14]),
        .RESULT_DATA15             (cim_result_data[15]),
        .RESULT_DATA16             (cim_result_data[16]),
        .RESULT_DATA17             (cim_result_data[17]),
        .RESULT_DATA18             (cim_result_data[18]),
        .RESULT_DATA19             (cim_result_data[19]),
        .RESULT_DATA20             (cim_result_data[20]),
        .RESULT_LAST               (cim_result_last)
    );

    // The current FPGA primitive carries two error bits.  The behavioral
    // model has a third error bit, so direct-FPGA integration holds it low.
    assign cim_error[2] = 1'b0;

    assign set_result_mode      = set_auto_result[20:19];
    assign set_result_column    = set_auto_result[18:14];
    assign reset_result_mode    = reset_auto_result[20:19];
    assign reset_result_column  = reset_auto_result[18:14];

endmodule

`default_nettype wire



